html:
{%- import 'afintrix_theme/templates/print/afintrix_print.html' as afx -%}
<div class="afx-print">
	{{ afx.head(_('Invoice'), doc.name, [
		(_('Date'), frappe.utils.formatdate(doc.posting_date)),
		(_('Due'), frappe.utils.formatdate(doc.due_date)),
		(_('PO'), doc.po_no),
	]) }}

	{{ afx.parties([
		(_('Billed to'), doc.customer_name, doc.address_display or ''),
		(_('From'), doc.company, doc.company_address_display or ''),
	]) }}

	{{ afx.table_open([
		(_('Item'), '46%', 'left'),
		(_('Qty'), '12%', 'right'),
		(_('Rate'), '18%', 'right'),
		(_('Amount'), '20%', 'right'),
	]) }}
	{%- for row in doc.items %}
	<tr>
		<td>{{ loop.index }}</td>
		{{ afx.item_cell(row.item_name, row.description) }}
		<td class="text-right">{{ row.qty }} {{ row.uom or '' }}</td>
		<td class="text-right">{{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}</td>
		<td class="text-right">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
	</tr>
	{%- endfor %}
	{{ afx.table_close() }}

	{{ afx.summary([
		(_('Net total'), frappe.utils.fmt_money(doc.net_total, currency=doc.currency), False),
		(_('Taxes'), frappe.utils.fmt_money(doc.total_taxes_and_charges, currency=doc.currency) if doc.total_taxes_and_charges else none, False),
		(_('Grand total'), frappe.utils.fmt_money(doc.grand_total, currency=doc.currency), True),
		(_('Outstanding'), frappe.utils.fmt_money(doc.outstanding_amount, currency=doc.currency) if doc.outstanding_amount else none, False),
	]) }}

	{{ afx.terms(_('Terms'), doc.terms) }}
</div>
